#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
//
// The mirror rate-limits one package per check (HTTP 429). Instead of
// failing the whole check on a transient 429, we retry that package after a
// short delay and only report a 429 as an error if it persists. Every
// dependency is still verified before the check is allowed to pass.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// The mirror rate-limits one package per check; the slot rotates with the
// run number. A 429 is transient — the mirror is busy, not broken — so we
// retry after a short backoff instead of failing the whole check.
function backoffMillis(attempt) {
  return 2000 * attempt; // 2s, 4s, 6s, ...
}

// Synchronous sleep so we can keep the existing single-process flow.
function sleep(ms) {
  const end = Date.now() + ms;
  while (Date.now() < end) { /* spin */ }
}

// Ask the mirror (the registry/ mirror) for one dependency's metadata.
// Returns { ok } or { rateLimited } or { notFound }.
function fetchMeta(name) {
  const file = path.join("registry", name + ".json");
  if (!fs.existsSync(file)) {
    return { notFound: true };
  }
  const meta = JSON.parse(fs.readFileSync(file, "utf8"));
  if (!meta.versions || !meta.versions.includes(pkg.dependencies[name])) {
    return { notFound: true };
  }
  return { ok: true };
}

// Simulate the mirror's rotating rate-limit: one package per check, the
// slot moving with the run number. The rate-limit itself is transient:
// after a brief delay the mirror will serve the package normally.
function isRateLimited(name, checkRun) {
  return name === deps[checkRun % deps.length];
}

// Verify one dependency, retrying on a transient 429.
function verify(name, checkRun, maxAttempts) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    if (isRateLimited(name, checkRun) && attempt === 1) {
      console.error("ERR! 429 Too Many Requests: " + name +
        " (registry mirror busy, retry in a few seconds)");
      // Transient rate-limit: back off and retry.
      const delay = backoffMillis(attempt);
      console.error("... retrying " + name + " in " + (delay / 1000) + "s");
      sleep(delay);
      continue;
    }
    const res = fetchMeta(name);
    if (res.ok) {
      console.log("ok " + name + "@" + pkg.dependencies[name]);
      return true;
    }
    if (res.notFound) {
      console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
        " not on mirror");
      return false;
    }
  }
  console.error("ERR! 429 Too Many Requests: " + name +
    " (registry mirror still busy after " + maxAttempts + " attempts)");
  return false;
}

const MAX_ATTEMPTS = 5;
let failed = false;
for (const name of deps) {
  if (!verify(name, run, MAX_ATTEMPTS)) {
    failed = true;
  }
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
}
console.log("all dependencies resolve");
